#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Every open PR, merged on all-open-prs, tried on this Mac (TESTING-ALL-OPEN-PRS.md says what each
# one is). What a script can check it checks; the rest it asks, one check at a time. Each answer is
# kept in run/all-open-prs-macos/results.txt with the logs, and a run again offers it back.

TOTAL_STAGES=16

[[ "$(uname -s)" == Darwin ]] || { echo "This one is for macOS; TESTING-ALL-OPEN-PRS.md has Omarchy's checks." >&2; exit 1; }

ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)
cd "$ROOT"
HUD="$ROOT/bin/zmk-layer-hud"
OUT="$ROOT/run/all-open-prs-macos"     # run/ is ignored: nothing here is committed
mkdir -p "$OUT"
ENV_FILE="$OUT/results.txt"
STATE="${ZMKHUD_STATE:-${XDG_STATE_HOME:-$HOME/.local/state}/zmk-layer-hud}"
LOGS=("$STATE/panel.log" "$STATE/hudfeed.log")   # the macOS panel runs the feed: its lines are in panel.log

# The copy `zmk-layer-hud` on PATH runs, when it is another tree: stopped for the tests, back after.
INSTALLED=""; INSTALLED_ROOT=""; WAS_RUNNING=no; WAS_ICON=no; SWITCHED=no
if command -v zmk-layer-hud >/dev/null 2>&1; then
  INSTALLED_ROOT=$(python3 -c 'import os, sys; print(os.path.dirname(os.path.dirname(os.path.realpath(sys.argv[1]))))' \
                   "$(command -v zmk-layer-hud)")
  [[ "$INSTALLED_ROOT" != "$ROOT" ]] && INSTALLED="$INSTALLED_ROOT/bin/zmk-layer-hud"
fi

# record ID RESULT TEXT: one answer, kept.
record() {
  write_env "R_$1" "$2 · $3" >/dev/null
  case $2 in
    pass) printf '  %s✓ %s%s\n' "$GREEN" "$3" "$RESET" ;;
    fail) printf '  %s✗ %s%s\n' "$RED" "$3" "$RESET" ;;
    *)    printf '  %s– %s (skipped)%s\n' "$DIM" "$3" "$RESET" ;;
  esac
}

# auto ID "what" CMD...: a check this script makes itself; CMD's output goes to run/.../ID.log.
auto() {
  local id=$1 what=$2; shift 2
  if "$@" >"$OUT/$id.log" 2>&1; then record "$id" pass "$what"
  else record "$id" fail "$what (run/all-open-prs-macos/$id.log)"; fi
}

# check ID "question": a check only you can make.
check() {
  local id=$1 q=$2 was a why
  was=$(_existing "R_$id" || true)
  while :; do
    printf '  %s?%s %s %s[p]ass [f]ail [s]kip%s%s ' "$YELLOW" "$RESET" "$q" "$DIM" \
      "${was:+, Enter keeps ${was%% ·*}}" "$RESET"
    read -r a || { record "$id" skip "$q"; return; }
    case $a in
      p|P) record "$id" pass "$q"; return ;;
      f|F) printf '    what happened? '; read -r why || true; record "$id" fail "$q -- $why"; return ;;
      s|S) record "$id" skip "$q"; return ;;
      "")  [[ -n $was ]] && { note "kept: ${was%% ·*}"; return; } ;;
    esac
  done
}

# hud_is KEY VALUE ...: status --json gives each KEY that VALUE, spelled as Python prints it.
hud_is() {
  "$HUD" status --json | python3 -c '
import json, sys
h, a = json.load(sys.stdin), sys.argv[1:]
bad = [f"{k}={h.get(k)!r}" for k, v in zip(a[::2], a[1::2]) if str(h.get(k)) != v]
print("not so: " + ", ".join(bad) if bad else "so")
sys.exit(1 if bad else 0)' "$@"
}

# wait_for SECONDS CMD...: CMD again until it succeeds or the time is up.
wait_for() {
  local deadline=$((SECONDS + $1)); shift
  until "$@" >/dev/null 2>&1; do
    (( SECONDS < deadline )) || { "$@"; return 1; }
    sleep 0.5
  done
  "$@"
}

not() { ! "$@"; }
# says PATTERN CMD...: CMD's output, whatever its exit, matches PATTERN. (Not CMD | grep -q: under
# pipefail a grep that quits at its match can leave CMD a SIGPIPE, and the match counts as a miss.)
says() {
  local pattern=$1 out; shift
  out=$("$@" 2>&1) || true
  printf '%s\n' "$out"
  grep -qE "$pattern" <<<"$out"
}
verb() { "$HUD" "$1" && wait_for 10 hud_is shown "$2"; }        # verb VERB SHOWN-AFTER
docked() { says '^dock: docked' "$HUD" dock status; }
dock_to() { "$HUD" dock "$1" && if [[ $1 == on ]]; then wait_for 15 docked; else wait_for 15 not docked; fi; }
up() { wait_for 30 hud_is said True shown True; }
bring_back() {
  if hud_is running True >/dev/null 2>&1; then "$HUD" show >/dev/null 2>&1 || true
  else "$HUD" start >/dev/null 2>&1 || true; fi
  up >/dev/null || warn "the HUD is not back up: $HUD status says why"
}

# mark, then since_mark: what the logs said after the mark; said_since PATTERN: whether it is there.
mark() {
  MARK=()
  local f
  for f in "${LOGS[@]}"; do MARK+=("$( [[ -f $f ]] && wc -c <"$f" | tr -d ' ' || echo 0)"); done
}
since_mark() {
  local i
  for i in "${!LOGS[@]}"; do
    [[ -f ${LOGS[$i]} ]] && tail -c +"$(( ${MARK[$i]:-0} + 1 ))" "${LOGS[$i]}"
  done
  return 0
}
said_since() { since_mark | grep -qE "$1"; }
indent() { sed 's/^/    /'; }

# put_back: the branch's HUD and icon away, and the installed ones as they were.
put_back() {
  [[ $SWITCHED == yes ]] || return 0
  SWITCHED=no
  "$HUD" dock off >/dev/null 2>&1 || true
  "$HUD" stop >>"$OUT/switch.log" 2>&1 || true
  if [[ -n $INSTALLED ]]; then
    "$HUD" menubar disable >>"$OUT/switch.log" 2>&1 || true
    if [[ $WAS_ICON == yes ]]; then "$INSTALLED" menubar enable >>"$OUT/switch.log" 2>&1 || warn "the installed icon did not come back: $INSTALLED menubar enable"; fi
    if [[ $WAS_RUNNING == yes ]]; then "$INSTALLED" start >>"$OUT/switch.log" 2>&1 || warn "the installed HUD did not start: $INSTALLED start"; fi
  fi
}
trap 'printf "\n"; warn "stopped: putting things back"; put_back; exit 130' INT

banner "Every open PR, on this Mac"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "This branch"
auto branch "on all-open-prs" test "$(git rev-parse --abbrev-ref HEAD)" = all-open-prs
note "commit $(git rev-parse --short HEAD): $(git log -1 --format=%s)"
if [[ ! -x "$ROOT/.venv/bin/python3" ]]; then
  warn "no venv in $ROOT: run \`make venv\` (or symlink a clone's .venv here), then this again"
  exit 1
fi
record venv pass "a venv to run under"
if [[ -n $INSTALLED ]]; then
  note "installed copy: $INSTALLED_ROOT (stopped for the tests, started again at the end)"
else
  note "no other copy installed: zmk-layer-hud on PATH is this tree, or there is none"
fi
pause "Enter to run the test suites (about three minutes)"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "The test suites"
say "make test under the venv's Python. This Mac has the ports and ptys, so the tests a sandbox"
say "skips run too, the end-to-end remote visit among them."
note "running; the output goes to run/all-open-prs-macos/suites.log"
if make test PYTHON="$ROOT/.venv/bin/python3" >"$OUT/suites.log" 2>&1; then record suites pass "make test"
else record suites fail "make test (run/all-open-prs-macos/suites.log)"; fi
grep -E '^Ran [0-9]+ tests|^OK|^FAILED|checks, [0-9]+ failures' "$OUT/suites.log" | head -20 | indent || true
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "The tablet apps' suites"
say "The iPad keyboard's Core (swift test) and the Android sink (Gradle); each skips without its tool."
for t in ios android; do
  if make "test-$t" >"$OUT/test-$t.log" 2>&1; then
    if grep -q "skipping" "$OUT/test-$t.log"; then record "test_$t" skip "make test-$t: $(grep -m1 skipping "$OUT/test-$t.log")"
    else record "test_$t" pass "make test-$t"; fi
  else record "test_$t" fail "make test-$t (run/all-open-prs-macos/test-$t.log)"; fi
done
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "The branch's HUD in place of the installed one"
SWITCHED=yes
if [[ -n $INSTALLED ]]; then
  if says '^panel: running' "$INSTALLED" status >/dev/null; then WAS_RUNNING=yes; fi
  if says 'icon is on' "$INSTALLED" menubar status >/dev/null; then WAS_ICON=yes; fi
  say "The installed HUD (running: $WAS_RUNNING) and its icon (on: $WAS_ICON) are put away."
  "$INSTALLED" stop >"$OUT/switch.log" 2>&1 || true
  if [[ $WAS_ICON == yes ]]; then "$INSTALLED" menubar disable >>"$OUT/switch.log" 2>&1 || true; fi
fi
"$HUD" stop >>"$OUT/switch.log" 2>&1 || true
auto start "the branch's HUD starts" "$HUD" start
auto icon_on "its menubar icon comes up" "$HUD" menubar enable
auto said "status --json: running, said, ours, shown" up
auto status_ours "status --json: ours" hud_is running True ours True
auto feed_in_panel "status --json: the feed runs in the panel" hud_is feed "in the panel"
auto status_line "status: panel: running, shown" says '^panel: running, shown' "$HUD" status
auto status_json "status --json: one JSON object" sh -c '"$1" status --json | python3 -c "import json, sys; assert isinstance(json.load(sys.stdin), dict)"' _ "$HUD"
"$HUD" status 2>&1 | indent || true
check hud_drawn "Is the HUD on screen, drawing your board?"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Show, hide, toggle (#9, #13)"
auto hide "hide: shown False" verb hide False
check hide_seen "Is the HUD off screen?"
auto show "show: shown True" verb show True
check show_seen "Is it back?"
auto toggle_off "toggle hides it" verb toggle False
auto toggle_on "toggle shows it again" verb toggle True
step "Press Ctrl+Alt+L once."
auto hotkey_off "Ctrl+Alt+L hides it" wait_for 30 hud_is shown False
step "And again."
auto hotkey_on "Ctrl+Alt+L shows it again" wait_for 30 hud_is shown True
step "Click the hide button on the HUD itself."
auto page_hide "the page's hide button hides it" wait_for 30 hud_is shown False
bring_back
step "Hover the HUD's ✕, then click it."
check page_close "Did the ✕ do what it says?"
bring_back

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Where it was left (#9)"
step "Drag the HUD somewhere else on the screen."
pause "Enter once it is there"
auto restart "restart" "$HUD" restart
auto restart_up "it is up again" up
check place_kept "Did it come back where you left it?"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "A second copy (#13)"
say "With this copy's HUD running, another copy of the branch should say where it runs, and its"
say "hide and power leave this one alone."
SECOND=""
if confirm "Make that copy now (a git worktree in a temp directory, removed after)?"; then
  TMP2=$(mktemp -d "${TMPDIR:-/tmp}/zmkhud-second.XXXXXX")
  SECOND="$TMP2/zmk-layer-hud"
  if ! git worktree add --detach "$SECOND" HEAD >"$OUT/second.log" 2>&1; then
    record second_copy fail "the second copy could not be made (run/all-open-prs-macos/second.log)"
    rm -rf "$TMP2"
    SECOND=""
  fi
else
  record second_copy skip "a second copy's verbs"
fi
if [[ -n $SECOND ]]; then
  ln -s "$(cd "$ROOT/.venv" && pwd -P)" "$SECOND/.venv"
  S="$SECOND/bin/zmk-layer-hud"
  auto second_status "its status names where the HUD runs" says "from $ROOT" "$S" status
  "$S" hide >>"$OUT/second.log" 2>&1 || true
  auto second_hide "its hide leaves the HUD shown" hud_is running True ours True shown True
  "$S" power >>"$OUT/second.log" 2>&1 || true
  sleep 3
  auto second_power "its power neither stops this HUD nor starts another" hud_is running True said True ours True
  note "what the second copy said:"
  grep -v '^Preparing worktree\|^HEAD is now' "$OUT/second.log" | tail -6 | indent || true
  check second_words "Does it say where the HUD runs, and is the HUD as it was?"
  git worktree remove --force "$SECOND" >>"$OUT/second.log" 2>&1 || warn "remove it by hand: git worktree remove --force $SECOND"
  rm -rf "$TMP2"
  bring_back
fi
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "The menubar icon (#9, #13)"
auto icon_status "menubar status: on" says 'icon is on' "$HUD" menubar status
check icon_shown "HUD shown: does the icon show a WPM, and its menu the stats and the WPM choice?"
check stats_site "Does the heading of the HUD's stats column open the site?"
check session_menu "Right-click the HUD: does its session menu save a session, then load it?"
"$HUD" hide >/dev/null 2>&1 || true
check icon_hidden "HUD hidden: does the icon say so, and does a click bring the HUD back?"
"$HUD" stop >/dev/null 2>&1 || true
check icon_stopped "HUD stopped: does the icon say so, and does a click start it?"
bring_back

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Docked, and typing (#1, #9)"
auto dock_on "dock on docks it" dock_to on
"$HUD" dock status 2>&1 | indent || true
if ! says 'can type' "$HUD" typing status >/dev/null; then
  say "It may not type yet: the HUD asks for Accessibility now."
  "$HUD" typing setup 2>&1 | indent || true
  step "Grant it in System Settings › Privacy & Security › Accessibility, to the app the prompt names."
  pause "Enter once granted"
fi
auto typing_ok "typing status: can type" says 'can type' "$HUD" typing status
check grant "Did the grant go to the app the prompt named?"
step "Open TextEdit and click a sentence out on the docked keyboard."
check types "Does it type there, with TextEdit keeping the focus?"
check repeat "Hold a key down on the docked keyboard: does it repeat?"
check real_size "Measure a key with a ruler: is it 18 mm?"
check fits "Does the board fit along the bottom, the halves at the sides, the column between them?"
check minimize "Minimize it: does it leave a bar, and come back from it?"
check detach "Detach it from its banner, then attach it: does it float, then dock again?"
check redock "Change the display (resolution, or a monitor in or out): does it dock again on the new one?"
check too_big "On a screen too small for the board: does it float, and dock status say why? (skip without one)"
auto dock_off "dock off floats it" dock_to off

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Keys and combos on the page (#6, #8)"
say "On your keyboard, watching the HUD."
check named_keys "Tab, Esc, Page Down, Delete, Caps Lock: does each light the key drawn with its word?"
check strip_glyphs "Type Tab, ⌘⇧C, F5, Return, ⌥←: does the strip draw ⇥ ⌘⇧C F5 ↵ ⌥←?"
check combo_layer "A layer held that declares no combo there, strike a base combo's keys: two presses, no combo?"
check combo_pill "A combo on the base layer: does its pill show and its keys ring?"

# ── 11 ────────────────────────────────────────────────────────────────────
stage "The keyboard over USB (#12)"
step "Have the keyboard on USB alone: BLE off, or on another profile."
pause "Enter once it is"
check usb_reads "Do the layers follow, keys light by position, and the strip show what you type?"
mark
step "Hold Shift and, holding it, unplug the keyboard. Then let go."
pause "Enter once it is unplugged"
check shift_let_go "Has the board let Shift go (no ⇧ held on the HUD)?"
note "giving the feed 10 s to look for it again…"
sleep 10
n=$(since_mark | grep -c "no serial port" || true)
if [[ $n -eq 1 ]]; then record serial_note pass "unplugged, the log says once that no serial port is the keyboard's"
else record serial_note fail "unplugged, the log said \"no serial port\" $n times, not once"; fi
since_mark | grep "hudfeed: " | tail -4 | indent || true
mark
step "Plug it back in."
auto usb_back "the feed reads it again" wait_for 60 said_since 'hudfeed: reading .* on /dev/'
check usb_again "Does the board follow it again?"

# ── 12 ────────────────────────────────────────────────────────────────────
stage "The keyboard over BLE (#12)"
mark
step "Unplug the USB cable and connect the keyboard over BLE."
auto ble_reading "the log says it reads it over BLE" wait_for 120 said_since 'hudfeed: reading .* over BLE'
check ble_works "Do the layers and the strip follow it over BLE?"
mark
step "Switch the keyboard off."
auto ble_gone "the log says it is gone" wait_for 60 said_since 'over BLE gone'
say "The feed is searching for it now. Stopping the HUD, timed:"
t0=$(python3 -c 'import time; print(time.time())')
"$HUD" stop >"$OUT/ble-stop.log" 2>&1 || true
dt=$(python3 -c 'import sys, time; print(f"{time.time() - float(sys.argv[1]):.1f}")' "$t0")
if python3 -c 'import sys; sys.exit(0 if float(sys.argv[1]) <= 3 else 1)' "$dt"; then
  record ble_stop pass "stop while it searches quits at once (${dt} s)"
else record ble_stop fail "stop while it searches took ${dt} s"; fi
auto ble_stopped "nothing of it is left running" hud_is running False feed stopped
mark
bring_back

# ── 13 ────────────────────────────────────────────────────────────────────
stage "USB and BLE at once (#16)"
both() { said_since 'hudfeed: reading .* on /dev/' && said_since 'hudfeed: reading .* over BLE'; }
step "Switch the keyboard on over BLE, and plug it in by USB too."
auto both_read "the feed reads it on both" wait_for 120 both
check once "Type a word you know the length of: is each key in the strip once, and counted once?"
check chord "Hold a combo down: does it light once, no key pressed twice?"
step "Unplug USB, with a layer held if you can."
check takeover "Does the HUD go on over BLE at once, on the layer it should?"
step "Plug it back in."
check replug_both "On both again: is every key still shown once?"
serial=$( { cat "${LOGS[@]}" 2>/dev/null || true; } | sed -nE 's/.*hudfeed: reading (.+) on \/dev\/.*/\1/p' | tail -1)
typed=$( { cat "${LOGS[@]}" 2>/dev/null || true; } | sed -nE 's/.*hudfeed: reading what is typed on (.+) \(.*/\1/p' | tail -1)
note "the serial port calls it \"${serial:-?}\"; the HID reader \"${typed:-?}\""
if [[ -n $serial && $serial == "$typed" ]]; then record names_alike pass "the serial port and the HID reader name it alike"
else record names_alike fail "the serial port and the HID reader name it apart (\"$serial\", \"$typed\"): the page may count two devices"; fi

# ── 14 ────────────────────────────────────────────────────────────────────
stage "The keymap tools (#10, #11)"
auto keymap_loads "keymap: the config and the definitions load" "$HUD" keymap
auto missing_config "keymap --config of a file not there is an error" not "$HUD" keymap --config "$OUT/no-such-config.yaml"
auto doctor "doctor" "$HUD" doctor
tail -12 "$OUT/doctor.log" | indent || true
current=$(_existing KEYBOARDS || true)
[[ -z $current && -d "$HOME/projects/keyboards" ]] && current="$HOME/projects/keyboards"
ask KEYBOARDS "Your keyboards working copy${current:+ ($current)}; Enter keeps it, - skips:"
[[ -z $KEYBOARDS ]] && KEYBOARDS=$current
if [[ -n $KEYBOARDS && $KEYBOARDS != - && -d $KEYBOARDS ]]; then
  write_env KEYBOARDS "$KEYBOARDS" >/dev/null
  auto audit "make audit against it" make audit SOURCE="$KEYBOARDS"
  tail -6 "$OUT/audit.log" | indent || true
  if confirm "Run sync --watch? It writes the definitions again from their sources, as sync does."; then
    "$HUD" sync --watch >"$OUT/sync-watch.log" 2>&1 &
    W=$!
    sleep 5
    step "Edit the drawing's layout file in $KEYBOARDS and save; then undo it and save again."
    check watch_syncs "Did it sync each time (run/all-open-prs-macos/sync-watch.log), and the HUD redraw?"
    kill "$W" 2>/dev/null || true; wait "$W" 2>/dev/null || true
    tail -6 "$OUT/sync-watch.log" | indent || true
  else
    record watch_syncs skip "sync --watch"
  fi
else
  record audit skip "make audit"
  record watch_syncs skip "sync --watch"
fi
say "The demo, playing its script on a sample board in your browser:"
"$HUD" demo --play "$ROOT/docs/demo-type.json" --port 8797 --ws-port 8798 >"$OUT/demo.log" 2>&1 &
D=$!
check demo_plays "Does the demo type its script, keys and combos drawn?"
kill "$D" 2>/dev/null || true; wait "$D" 2>/dev/null || true

# ── 15 ────────────────────────────────────────────────────────────────────
stage "A tablet as the keyboard (#1)"
if confirm "Is there an iPad or Android tablet on this network to try?"; then
  "$HUD" remote on 2>&1 | tee "$OUT/remote.log" | indent || true
  step "Open that link on the tablet. If macOS asks whether to accept connections, allow it."
  check remote_browser "In the tablet's browser: does it show the board, and does a tap type here?"
  check remote_home "Added to the home screen and opened from there: the same?"
  check remote_firewall "Did the firewall prompt come, and did allowing it work?"
  auto remote_off "remote off" "$HUD" remote off
else
  record remote skip "a tablet in remote mode"
fi

# ── 16 ────────────────────────────────────────────────────────────────────
stage "Putting things back"
put_back
if [[ -n $INSTALLED ]]; then say "The branch's HUD and icon are stopped; the installed ones are as they were."
else say "The branch's HUD is stopped. Its icon stays: \`$HUD menubar disable\` puts it away."; fi
pause "Enter for the results"

WRITTEN_ENV=()   # the answers are summed up below, not listed key by key
finish
pass=$(grep -c '^R_[^=]*=pass' "$ENV_FILE" || true)
fail=$(grep -c '^R_[^=]*=fail' "$ENV_FILE" || true)
skip=$(grep -c '^R_[^=]*=skip' "$ENV_FILE" || true)
printf '  %s%s passed%s · %s%s failed%s · %s skipped\n' "$GREEN" "$pass" "$RESET" "$RED" "$fail" "$RESET" "$skip"
if (( fail )); then
  printf '\n'
  grep '^R_[^=]*=fail' "$ENV_FILE" | sed -E 's/^R_([^=]*)=fail · /  ✗ \1: /'
fi
note "every answer: $ENV_FILE"
printf '\n'
